// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Highlight } from "@/components/ui/highlight";
import { Icon } from "@/components/ui/icon";
import { Sticker } from "@/components/ui/sticker";
import { dollars, perMonth, type Period, type Tier } from "@/blocks/pricing-01/components/pricing-01-data";
import { cn } from "@/lib/utils";
export const Pricing01Card = defineUi<{
  id: string;
  tier: Tier;
  period: Period;
  chosen: boolean;
  onChoose: () => void;
}>("Pricing01Card", ["id", "tier", "period", "chosen", "onChoose"], (_props, {
  slots: _slots
}) => {
  const id = computed(() => _props["id"]);
  const tier = computed(() => _props["tier"]);
  const period = computed(() => _props["period"]);
  const chosen = computed(() => _props["chosen"]);
  const onChoose = computed(() => _props["onChoose"]);
  const free = computed(() => tier.value.monthly === 0);
  const title = computed(() => `${id.value}-title`);
  return () => {
    return <Card as="article" aria-labelledby={title.value} stock={tier.value.popular ? "card" as const : "paper" as const} tape="top" tapeKind={tier.value.tape} seed={`price-${tier.value.id}`} data-popular={tier.value.popular ? "" as const : undefined} class={cn("relative h-full", tier.value.popular && "@4xl/pricing:-my-4 @4xl/pricing:pt-10 @4xl/pricing:pb-10")}>
      {tier.value.popular ? <Sticker name="first-place" size={76} rotate={10} seed="popular" class="absolute -end-2 -top-9 z-10 @4xl/pricing:-end-5" /> : null}
      <CardHeader>
        <CardTitle id={title.value} role="heading" aria-level={3} class="text-3xl">
          {tier.value.popular ? <Highlight>{tier.value.name}</Highlight> : tier.value.name}
          {tier.value.popular ? <Badge size="sm" class="ms-3 align-middle">
              Most popular
            </Badge> : null}
        </CardTitle>
        <CardDescription>{tier.value.tagline}</CardDescription>
      </CardHeader>
      <CardContent class="grid flex-1 content-start gap-6">
        <div>
          <p class="flex items-baseline gap-2.5">
            <span class="ll-num font-script text-6xl leading-none font-bold">{dollars(perMonth(tier.value, period.value))}</span>
            <span class="text-muted-foreground">{free.value ? "forever" as const : "a month" as const}</span>
          </p>
          <p class="mt-1 h-5 text-sm text-muted-foreground">{free.value ? "No card needed" as const : period.value === "yearly" ? `billed ${dollars(tier.value.yearly)} once a year` : "billed monthly" as const}</p>
        </div>
        <ul class="grid gap-2.5" aria-label={`${tier.value.name} includes`}>
          {tier.value.features.map(f => <li key={f} class="flex items-start gap-2.5">
              <Icon name="check" class="mt-1 text-green" weight={1.3} />
              <span>{f}</span>
            </li>)}
        </ul>
      </CardContent>
      <CardFooter>
        <Button class="w-full" size="lg" variant={tier.value.popular ? "default" as const : "outline" as const} aria-pressed={chosen.value} onClick={onChoose.value}>
          {chosen.value ? "Picked" as const : tier.value.cta}
          {chosen.value ? <Icon name="check" /> : null}
        </Button>
      </CardFooter>
    </Card>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
export type Period = "monthly" | "yearly";
export type Tier = {
  id: "starter" | "studio" | "workshop";
  name: string;
  tagline: string;
  monthly: number;
  yearly: number;
  features: string[];
  cta: string;
  popular?: boolean;
  tape: "masking" | "washi-dots" | "washi-stripes";
};
export const TIERS: Tier[] = [{
  id: "starter" as const,
  name: "Starter" as const,
  tagline: "One notebook, one pen, no rush." as const,
  monthly: 0,
  yearly: 0,
  features: ["3 notebooks", "1 GB of paper", "Just you at the desk", "Help from the community"],
  cta: "Start for free" as const,
  tape: "masking" as const
}, {
  id: "studio" as const,
  name: "Studio" as const,
  tagline: "Ten notebooks and the good highlighters." as const,
  monthly: 1200,
  yearly: 12000,
  features: ["10 notebooks", "10 GB of paper", "3 people at the desk", "The good highlighters", "Email help, same day"],
  cta: "Get Studio" as const,
  popular: true,
  tape: "washi-dots" as const
}, {
  id: "workshop" as const,
  name: "Workshop" as const,
  tagline: "A whole desk. Washi tape included." as const,
  monthly: 3200,
  yearly: 32000,
  features: ["100 notebooks", "100 GB of paper", "15 people at the desk", "Unlimited washi tape", "A real person, quickly"],
  cta: "Get Workshop" as const,
  tape: "washi-stripes" as const
}];
export const dollars = (cents: number): string => `$${cents % 100 === 0 ? cents / 100 : (cents / 100).toFixed(2)}`;
export const perMonth = (t: Tier, period: Period): number => period === "yearly" ? Math.round(t.yearly / 12) : t.monthly;
export const FAQ = [{
  q: "Can I change plans later?" as const,
  a: "Any time. Going up starts today and you pay only the difference for the days that are left. Going down waits for your next renewal." as const
}, {
  q: "What happens if I run out of notebooks?" as const,
  a: "Nothing is deleted. The extra notebooks stay readable, and you can write in them again when there is room." as const
}, {
  q: "Is there a discount for schools or clubs?" as const,
  a: "Yes, 40% off for teachers, students and anyone running a club. Write to us from your school address and we will sort it out." as const
}, {
  q: "Do you take my card details on this page?" as const,
  a: "No. You pick a plan here and add a card on the next page, where it is checked and stored by our payment provider." as const
}];

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed, shallowRef, useId } from "vue";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
import { Doodle } from "@/components/ui/doodle";
import { Paper } from "@/components/ui/paper";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { Pricing01Card } from "@/blocks/pricing-01/components/pricing-01-card";
import { FAQ, TIERS, dollars, type Period, type Tier } from "@/blocks/pricing-01/components/pricing-01-data";
import { cn } from "@/lib/utils";
type Props = {
  className?: string;
  defaultPeriod?: Period;
  onChoose?: (tier: Tier, period: Period) => void;
};
const Pricing01 = defineUi<Props>("Pricing01", ["class", "defaultPeriod", "onChoose"], (_props, {
  slots: _slots
}) => {
  const className = computed(() => _props["class"]);
  const defaultPeriod = computed(() => _props["defaultPeriod"] === undefined ? "monthly" as const : _props["defaultPeriod"]);
  const onChoose = computed(() => _props["onChoose"]);
  const period = shallowRef<Period>(initialState(defaultPeriod.value));
  const setPeriod = stateSetter(period);
  const chosen = shallowRef<Tier["id"] | null>(initialState(null));
  const setChosen = stateSetter(chosen);
  const uid = useId();
  const yearlySaving = computed(() => TIERS.find(t => t.popular)!);
  const saved = computed(() => yearlySaving.value.monthly * 12 - yearlySaving.value.yearly);
  return () => {
    return <section aria-labelledby={`${uid}-title`} class={cn("@container/pricing mx-auto grid w-full max-w-6xl gap-12 px-4 py-12 sm:px-8", className.value)}>
      <header class="mx-auto grid max-w-2xl justify-items-center gap-4 text-center">
        <h2 id={`${uid}-title`} class="ll-riso font-script text-5xl leading-none font-bold text-balance @lg/pricing:text-6xl">
          Pick a desk that fits
        </h2>
        <p class="text-lg text-muted-foreground text-balance">Start free with one notebook. Pay when you need more paper, more people or the good highlighters. Cancel with one press.</p>
        <div class="mt-2 flex flex-wrap items-center justify-center gap-x-3 gap-y-1">
          <ToggleGroup type="single" variant="outline" size="lg" value={period.value} onValueChange={v => v && setPeriod(v as Period)} aria-label="Billing period">
            <ToggleGroupItem value="monthly">Monthly</ToggleGroupItem>
            <ToggleGroupItem value="yearly">Yearly</ToggleGroupItem>
          </ToggleGroup>
          <span class="flex items-end gap-1 font-script text-2xl leading-none text-ink-soft">
            <Doodle name="arrow-swoop" size={48} class="-scale-x-100 rtl:scale-x-100" />
            two months free
          </span>
        </div>
      </header>

      <p role="status" class="sr-only">
        {period.value === "yearly" ? `Showing yearly prices. Studio saves you ${dollars(saved.value)} a year.` : "Showing monthly prices." as const}
      </p>

      <div class="mx-auto grid w-full max-w-md gap-12 pt-6 @4xl/pricing:max-w-none @4xl/pricing:grid-cols-3 @4xl/pricing:items-stretch @4xl/pricing:gap-8">
        {TIERS.map(t => <Pricing01Card key={t.id} id={`${uid}-${t.id}`} tier={t} period={period.value} chosen={chosen.value === t.id} onChoose={() => {
          setChosen(t.id);
          onChoose.value?.(t, period.value);
        }} />)}
      </div>

      <Paper as="section" stock="slip" tilt={-0.3} seed="pricing-faq" aria-labelledby={`${uid}-faq`} class="mx-auto grid w-full max-w-2xl gap-4 px-6 py-6">
        <h3 id={`${uid}-faq`} class="font-script text-3xl leading-none font-semibold">
          Questions people ask
        </h3>
        <Accordion type="single" collapsible>
          {FAQ.map((f, i) => <AccordionItem key={f.q} value={`q${i}`}>
              <AccordionTrigger>{f.q}</AccordionTrigger>
              <AccordionContent>{f.a}</AccordionContent>
            </AccordionItem>)}
        </Accordion>
      </Paper>
    </section>;
  };
});
export default Pricing01;
